<?php
$period=in_array($_GET['period'] ?? '',['months','days','weeks'],true)?$_GET['period']:'days';
$month=is_string($_GET['month'] ?? '')?($_GET['month'] ?? ''):'';
$stats=cms_dashboard($period,$month); $max=max(1,...array_values($stats['buckets']));
?>
<section class="dashboard-intro"><p class="eyebrow">Visão geral</p><h2>Seu site em números</h2><p>Acompanhe seu conteúdo e o interesse dos leitores.</p></section>
<div class="dashboard-stats"><article><span>Visitas no período</span><strong><?=$stats['visits']?></strong></article><article><span>Páginas acessadas</span><strong><?=$stats['pages']?></strong></article><article><span>Notícias publicadas</span><strong><?=count(cms_news_entries())?></strong></article><article><span>Fontes RSS ativas</span><strong><?=(int)cms_db()->query('SELECT COUNT(*) FROM sources WHERE active=1')->fetchColumn()?></strong></article></div>
<section class="panel-card"><div class="dashboard-chart-heading"><h3>Visitas ao site</h3><form method="get" class="chart-filter"><input type="hidden" name="area" value="dashboard"><label>Visualização<select name="period"><option value="days" <?=$period==='days'?'selected':''?>>Dias do mês</option><option value="weeks" <?=$period==='weeks'?'selected':''?>>Semanas do mês</option><option value="months" <?=$period==='months'?'selected':''?>>Mês a mês</option></select></label><label>Mês / ano<input type="month" name="month" value="<?=rss_escape($stats['month'])?>" required></label><button>Aplicar</button></form></div>
<div class="visits-chart" role="img" aria-label="Gráfico de visitas no período selecionado"><?php foreach($stats['buckets'] as $label=>$total): ?><div class="chart-column"><span class="chart-count"><?=$total?></span><div class="chart-track"><div class="chart-bar" style="height:<?=round($total/$max*100,2)?>%" title="<?=rss_escape($label)?>: <?=$total?> visitas"></div></div><span class="chart-label"><?=$period==='weeks'?'Sem. ':''?><?=rss_escape($label)?></span></div><?php endforeach; ?></div>
<p class="field-help">Visitas por sessão, com intervalo de 30 minutos. Semanas agrupam os dias 1–7, 8–14, 15–21, 22–28 e 29–31. Horário de Brasília. O próprio acesso autenticado ao painel não entra na contagem. Os dados começam nesta atualização.</p></section>
<section class="panel-card"><h3>5 matérias mais acessadas no período</h3><?php if(!$stats['ranking']): ?><p>Ainda não há acessos registrados neste período.</p><?php endif; ?><ol class="ranking-list"><?php foreach($stats['ranking'] as $entry): ?><li><a href="<?=rss_escape($entry['href'])?>"><?=rss_escape($entry['title'])?></a><strong><?=$entry['visits']?> visitas</strong></li><?php endforeach; ?></ol></section>
